-- ╔══════════════════════════════════════════════════════════════════════════════╗
-- ║  Core SDUI Gateway — Canonical Database Schema DDL (Oracle 23ai)            ║
-- ║  Includes Tables, Indexes, Constraints, and Metadata Comments                ║
-- ╚══════════════════════════════════════════════════════════════════════════════╝

-- 1. USERS
CREATE TABLE "USERS" (
  "USR_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_USERS" PRIMARY KEY,
  "USR_LOGIN_ID" VARCHAR2(255) UNIQUE NOT NULL,
  "USR_PASSWORD_HASH" VARCHAR2(512) NOT NULL,
  "USR_API_TOKEN" VARCHAR2(1024),
  "USR_TOKEN_EXPIRY" TIMESTAMP,
  "USR_IS_ACTIVE" NUMBER(1) DEFAULT 1 NOT NULL CONSTRAINT "CHK_USR_IS_ACTIVE" CHECK ("USR_IS_ACTIVE" IN (0, 1)),
  "USR_CREATED_AT" TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL
);

-- 2. SERVICE
CREATE TABLE "SERVICE" (
  "SVR_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_SERVICE" PRIMARY KEY,
  "SVR_NAME" VARCHAR2(255) NOT NULL,
  "SVR_ICON_URL" VARCHAR2(512),
  "SVR_BASE_API_URL" VARCHAR2(512) NOT NULL,
  "SVR_IS_ACTIVE" NUMBER(1) DEFAULT 1 NOT NULL CONSTRAINT "CHK_SVR_IS_ACTIVE" CHECK ("SVR_IS_ACTIVE" IN (0, 1)),
  "SVR_SORT_ORDER" NUMBER DEFAULT 1
);

-- 3. SERVICE_DETAILS
CREATE TABLE "SERVICE_DETAILS" (
  "SVRD_MENU_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_SERVICE_DETAILS" PRIMARY KEY,
  "SVR_ID" NUMBER NOT NULL,
  "SVRD_PARENT_MENU_ID" NUMBER,
  "SVRD_DISPLAY_ORDER" NUMBER DEFAULT 1,
  "SVRD_MENU_NAME" VARCHAR2(255) NOT NULL,
  "SVRD_MENU_CODE" VARCHAR2(64),
  "SVRD_MENU_URL" VARCHAR2(512),
  "SVRD_MENU_TYPE" VARCHAR2(64) DEFAULT 'MENU' NOT NULL,
  "SVRD_ALLOWED_ROLES" VARCHAR2(512),
  "SVRD_PAGE_ID" NUMBER,
  "SVRD_IS_ACTIVE" NUMBER(1) DEFAULT 1 NOT NULL CONSTRAINT "CHK_SVRD_IS_ACTIVE" CHECK ("SVRD_IS_ACTIVE" IN (0, 1)),
  "SVRD_CREATED_AT" TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL
);

-- 4. PAGE_TEMPLATE
CREATE TABLE "PAGE_TEMPLATE" (
  "PAGE_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_PAGE_TEMPLATE" PRIMARY KEY,
  "PAGE_TITLE" VARCHAR2(255) NOT NULL,
  "PAGE_LAYOUT_TYPE" VARCHAR2(64) NOT NULL,
  "PAGE_UI_BLUEPRINT" JSON NOT NULL,
  "PAGE_CUSTOM_JS_URL" VARCHAR2(512),
  "PAGE_VERSION" VARCHAR2(32) DEFAULT 'v1.0.0' NOT NULL
);

-- 5. PAGE_ACTION
CREATE TABLE "PAGE_ACTION" (
  "ACT_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_PAGE_ACTION" PRIMARY KEY,
  "SVRD_MENU_ID" NUMBER NOT NULL,
  "ACT_NAME" VARCHAR2(255) NOT NULL,
  "ACT_TYPE" VARCHAR2(64) NOT NULL,
  "ACT_HTTP_METHOD" VARCHAR2(16) DEFAULT 'POST',
  "ACT_TARGET_ENDPOINT" VARCHAR2(512),
  "ACT_TARGET_WIDGET" VARCHAR2(255),
  "ACT_JSON_SCHEMA" JSON,
  "ACT_VISIBILITY_RULE" JSON,
  "ACT_DISPLAY_ORDER" NUMBER DEFAULT 1
);

-- 6. BUSINESS_LOGIC_CONFIG
CREATE TABLE "BUSINESS_LOGIC_CONFIG" (
  "BL_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_BUSINESS_LOGIC_CONFIG" PRIMARY KEY,
  "ACT_ID" NUMBER NOT NULL,
  "BL_IDENTIFIER" VARCHAR2(255) NOT NULL,
  "BL_EXECUTION_PARAMS" JSON
);

-- 7. LOGIN_LOG
CREATE TABLE "LOGIN_LOG" (
  "LLOG_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_LOGIN_LOG" PRIMARY KEY,
  "USR_ID" NUMBER NOT NULL,
  "LLOG_IP_ADDRESS" VARCHAR2(64),
  "LLOG_USER_AGENT" VARCHAR2(512),
  "LLOG_STATUS" VARCHAR2(64) NOT NULL,
  "LLOG_CREATED_AT" TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL
);

-- 8. ACTIVITY_LOG
CREATE TABLE "ACTIVITY_LOG" (
  "ACT_LOG_ID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY CONSTRAINT "PK_ACTIVITY_LOG" PRIMARY KEY,
  "ACT_LOG_EVENT_ID" VARCHAR2(64) NOT NULL,
  "ACT_LOG_USER_ID" VARCHAR2(64) NOT NULL,
  "ACT_LOG_ACTION" VARCHAR2(256) NOT NULL,
  "ACT_LOG_REFERENCE_KEY" VARCHAR2(256),
  "ACT_LOG_PAYLOAD" CLOB,
  "ACT_LOG_SOURCE_IP" VARCHAR2(64),
  "ACT_LOG_CREATED_AT" TIMESTAMP(6) DEFAULT SYSTIMESTAMP NOT NULL
);

-- 9. Performance Indexes
CREATE INDEX "IDX_SVRD_SVR_ID" ON "SERVICE_DETAILS" ("SVR_ID");
CREATE INDEX "IDX_SVRD_PARENT_MENU_ID" ON "SERVICE_DETAILS" ("SVRD_PARENT_MENU_ID");
CREATE INDEX "IDX_SVRD_PAGE_ID" ON "SERVICE_DETAILS" ("SVRD_PAGE_ID");
CREATE INDEX "IDX_PAGE_ACTION_MENU" ON "PAGE_ACTION" ("SVRD_MENU_ID");
CREATE INDEX "IDX_ACT_LOG_EVENT_ID" ON "ACTIVITY_LOG" ("ACT_LOG_EVENT_ID");
CREATE INDEX "IDX_ACT_LOG_USER_ID" ON "ACTIVITY_LOG" ("ACT_LOG_USER_ID");
CREATE INDEX "IDX_ACT_LOG_ACTION" ON "ACTIVITY_LOG" ("ACT_LOG_ACTION");
CREATE INDEX "IDX_ACT_LOG_REF_KEY" ON "ACTIVITY_LOG" ("ACT_LOG_REFERENCE_KEY");
CREATE INDEX "IDX_ACT_LOG_CREATED_AT" ON "ACTIVITY_LOG" ("ACT_LOG_CREATED_AT");

-- 10. Column Comments
COMMENT ON COLUMN "USERS"."USR_TOKEN_EXPIRY" IS 'Session timeout & single device enforcement';
COMMENT ON COLUMN "SERVICE_DETAILS"."SVRD_MENU_URL" IS 'Frontend UI Route (e.g., /dynamic-page/account-stmt)';
COMMENT ON COLUMN "SERVICE_DETAILS"."SVRD_MENU_TYPE" IS 'ROOT, SUB_SERVICE, MENU, LEAF';
COMMENT ON COLUMN "SERVICE_DETAILS"."SVRD_ALLOWED_ROLES" IS 'e.g., "ADMIN,MAKER,CHECKER"';
COMMENT ON COLUMN "SERVICE_DETAILS"."SVRD_PAGE_ID" IS 'Links to PAGE_TEMPLATE';
COMMENT ON COLUMN "PAGE_TEMPLATE"."PAGE_LAYOUT_TYPE" IS 'Master container layout: SINGLE_COL, SPLIT_VIEW, TAB_VIEW, DASHBOARD_GRID';
COMMENT ON COLUMN "PAGE_TEMPLATE"."PAGE_UI_BLUEPRINT" IS 'JSON Tree defining Skeleton Objects (Forms, Grids, Cards), fields, validations, and data-binding keys';
COMMENT ON COLUMN "PAGE_TEMPLATE"."PAGE_CUSTOM_JS_URL" IS 'Nullable. Used ONLY if a specific page requires custom external JS override';
COMMENT ON COLUMN "PAGE_TEMPLATE"."PAGE_VERSION" IS 'Schema version (e.g., v1.0) for cache control';
COMMENT ON COLUMN "PAGE_ACTION"."ACT_NAME" IS 'e.g., Search, Submit, Approve, Clear';
COMMENT ON COLUMN "PAGE_ACTION"."ACT_TYPE" IS 'INITIAL_LOAD, SEARCH_API, BUSINESS_API, UI_RESET';
COMMENT ON COLUMN "PAGE_ACTION"."ACT_HTTP_METHOD" IS 'GET, POST, PUT';
COMMENT ON COLUMN "PAGE_ACTION"."ACT_TARGET_ENDPOINT" IS 'Backend API path';
COMMENT ON COLUMN "PAGE_ACTION"."ACT_TARGET_WIDGET" IS 'ID of the skeleton widget (e.g., grid_txn_list) that will render this actions response';
COMMENT ON COLUMN "PAGE_ACTION"."ACT_JSON_SCHEMA" IS 'Payload template, parameter mapping, and response translation rules';
COMMENT ON COLUMN "PAGE_ACTION"."ACT_VISIBILITY_RULE" IS 'Conditions defining when this button/action is enabled or visible';
COMMENT ON COLUMN "BUSINESS_LOGIC_CONFIG"."BL_IDENTIFIER" IS 'Backend service/handler identifier';
COMMENT ON COLUMN "ACTIVITY_LOG"."ALOG_REFERENCE_KEY" IS 'Indexed business key (Account No, NID) for instant audit lookup';

-- 11. Foreign Key Constraints
ALTER TABLE "SERVICE_DETAILS" ADD CONSTRAINT "FK_SVRD_SERVICE" FOREIGN KEY ("SVR_ID") REFERENCES "SERVICE" ("SVR_ID") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "SERVICE_DETAILS" ADD CONSTRAINT "FK_SVRD_PARENT" FOREIGN KEY ("SVRD_PARENT_MENU_ID") REFERENCES "SERVICE_DETAILS" ("SVRD_MENU_ID") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "SERVICE_DETAILS" ADD CONSTRAINT "FK_SVRD_PAGE" FOREIGN KEY ("SVRD_PAGE_ID") REFERENCES "PAGE_TEMPLATE" ("PAGE_ID") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "PAGE_ACTION" ADD CONSTRAINT "FK_ACT_SVRD" FOREIGN KEY ("SVRD_MENU_ID") REFERENCES "SERVICE_DETAILS" ("SVRD_MENU_ID") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "BUSINESS_LOGIC_CONFIG" ADD CONSTRAINT "FK_BL_ACT" FOREIGN KEY ("ACT_ID") REFERENCES "PAGE_ACTION" ("ACT_ID") DEFERRABLE INITIALLY IMMEDIATE;
ALTER TABLE "LOGIN_LOG" ADD CONSTRAINT "FK_LLOG_USR" FOREIGN KEY ("USR_ID") REFERENCES "USERS" ("USR_ID") DEFERRABLE INITIALLY IMMEDIATE;

